export function getFallbackPhoto(index) {
  const colors = ['#f43f5e', '#8b5cf6', '#06b6d4', '#10b981'];
  const color = colors[index % colors.length];
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="800" viewBox="0 0 600 800">
    <rect width="600" height="800" fill="#1c1917"/>
    <circle cx="300" cy="300" r="100" fill="${color}" opacity="0.8"/>
    <path d="M150 680 C150 500, 450 500, 450 680 Z" fill="${color}" opacity="0.6"/>
    <text x="300" y="740" font-family="sans-serif" font-size="28" fill="#ffffff" text-anchor="middle" opacity="0.8">Slot ${index + 1}</text>
  </svg>`;
  return `data:image/svg+xml;utf8,${encodeURIComponent(svg)}`;
}
